import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
import * as T from '../static/vendor/three-0.160.1.module.js';import Scene from '../static/pet-town-scene.js';import Town from '../static/pet-town-walk.js';
import {build,spec,inspectPassages,inspectJoints,inspectRoof} from '../static/pet-summer-pergola-proof-20261027/pergola.mjs';
import {placeAndProbe,segmentRectangleDistance,anchor} from '../static/pet-summer-pergola-proof-20261027/placement.mjs';import {fitView} from '../static/pet-scalloped-path-proof-20261027/framing.mjs';
const base=path.resolve(import.meta.dirname,'../static/pet-summer-pergola-proof-20261027'),near=(a,b,e=1e-6)=>assert.ok(Math.abs(a-b)<e,String(a)+' != '+String(b));
function topology(g){const p=g.attributes.position,n=g.attributes.normal,ix=g.index,edges=new Map(),v=i=>new T.Vector3().fromBufferAttribute(p,i),key=i=>v(i).toArray().map(x=>Math.round(x*1e7)).join(':');let volume=0,degenerate=0,negative=0;for(let i=0;i<(ix?ix.count:p.count);i+=3){const ids=[0,1,2].map(k=>ix?ix.getX(i+k):i+k),[a,b,c]=ids.map(v),cross=b.clone().sub(a).cross(c.clone().sub(a));if(cross.lengthSq()<1e-20){degenerate++;continue;}volume+=a.dot(b.clone().cross(c))/6;const normal=ids.map(k=>new T.Vector3().fromBufferAttribute(n,k)).reduce((a,b)=>a.add(b),new T.Vector3()).normalize();if(cross.clone().normalize().dot(normal)<=0)negative++;const ks=ids.map(key);for(let j=0;j<3;j++){const a=ks[j],b=ks[(j+1)%3],k=[a,b].sort().join('|'),r=edges.get(k)||{count:0,direction:0};r.count++;r.direction+=a<b?1:-1;edges.set(k,r);}}return{volume,degenerate,negative,badEdges:[...edges.values()].filter(x=>x.count!==2||x.direction!==0).length};}
function independentlyInside(mesh,worldPoint){const p=mesh.worldToLocal(worldPoint.clone()),proxy=new T.Mesh(mesh.geometry,mesh.material),old=mesh.material.side;mesh.material.side=T.DoubleSide;proxy.updateMatrixWorld(true);try{const ray=new T.Raycaster(p,new T.Vector3(.857,.371,.358).normalize());return new Set(ray.intersectObject(proxy,false).filter(h=>h.distance>1e-7).map(h=>Math.round(h.distance*1e7))).size%2===1;}finally{mesh.material.side=old;}}
const fixture=season=>{const world=Town.createWorld(),model=Scene.buildWorld(T,world,{},null,null,season),item=build(T);return{world,model,item,dispose(){item.dispose();model.dispose();}};};
test('27 real parts have closed outward geometry, positive scales, bottom/back faces and finite bounds',()=>{const a=build(T);assert.equal(a.parts.length,27);for(const p of a.parts){const r=topology(p.mesh.geometry);assert.deepEqual([r.badEdges,r.degenerate,r.negative],[0,0,0],p.id);assert.ok(r.volume>0&&p.mesh.scale.toArray().every(v=>v>0),p.id);assert.ok(p.mesh.matrixWorld.determinant()>0);}assert.deepEqual(a.bounds.min,[-1.21,0,-.98]);assert.deepEqual(a.bounds.max,[1.21,2.4,.98]);assert.equal(a.inspect().invalidNormals,0);assert.equal(a.inspect().invalidPositions,0);a.dispose();});
test('42 actual common-solid witnesses connect every foot post beam slat and both ends of eight braces',()=>{const a=build(T),r=inspectJoints(T,a);assert.equal(a.feet.length,4);assert.equal(a.posts.length,4);assert.equal(a.slats.length,7);assert.equal(a.braces.length,8);assert.equal(r.length,42);for(const row of r){assert.ok(row.insideA&&row.insideB,row.kind);const p=new T.Vector3(...row.point),ma=a.parts.find(x=>x.id===row.a).mesh,mb=a.parts.find(x=>x.id===row.b).mesh;assert.ok(independentlyInside(ma,p)&&independentlyInside(mb,p),row.kind+':'+row.a);}a.dispose();});
test('252 real front/back and side opening rays clear below authored1.90-world-unit height while occupied post rays hit',()=>{const a=build(T),r=inspectPassages(T,a);assert.equal(r.sampleCount,252);assert.equal(r.blocked,0);assert.ok(r.occupiedWitnesses.every(p=>p.hitParts.length===2));assert.deepEqual(new Set(r.rows.map(x=>x.axis)),new Set(['frontBack','sideSide']));assert.equal(r.bodyFit,false);assert.equal(r.continuousCollisionGuarantee,false);const ray=new T.Raycaster(new T.Vector3(0,2.25,1.1),new T.Vector3(0,0,-1),0,2.2);assert.ok(ray.intersectObjects(a.parts.map(p=>p.mesh),false).some(h=>h.object.name.startsWith('cross-roof-beam')));a.dispose();});
test('seven separate roof slats block21 finite vertical rays and18 real gaps remain open',()=>{const a=build(T),r=inspectRoof(T,a);assert.equal(r.occupiedRays,21);assert.equal(r.clearGapRays,18);assert.ok(r.occupied.every(x=>x.hits.some(n=>n.startsWith('separate-roof-slat'))));assert.ok(r.gaps.every(x=>x.hits.length===0));for(let i=1;i<a.slats.length;i++){const x=new T.Box3().setFromObject(a.slats[i-1]),y=new T.Box3().setFromObject(a.slats[i]);near(y.min.x-x.max.x,.235);}assert.equal(spec.physicalLoadVerified,false);a.dispose();});
test('20 actual sole rays and90 two-direction passage floor samples preserve existing world/surfaces/occluders',()=>{const f=fixture('summer'),before=JSON.stringify(f.world),surfaces=f.model.surfaces.slice(),occluders=f.model.occluders.slice(),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.deepEqual(p.townPoint,{x:1150,y:1350});assert.equal(p.supports.length,20);assert.equal(p.passageFloor.samples,90);assert.equal(p.finiteWalkability.samples,63);for(const row of p.supports)near(row.soleMinusFloor,0);assert.ok(p.passageFloor.rows.every(r=>r.walkable&&Math.abs(r.floorY-f.item.group.position.y)<.002));assert.equal(JSON.stringify(f.world),before);assert.deepEqual(f.model.surfaces,surfaces);assert.deepEqual(f.model.occluders,occluders);assert.deepEqual(f.item.group.scale.toArray(),[1,1,1]);assert.equal(p.notRegisteredAsTownSurface,true);assert.equal(p.bodyBinding,null);f.dispose();});
test('all2022 road triangles,141 original-card envelopes and every actual shoreline segment clear the full rectangle',()=>{const f=fixture('winter'),p=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(p.roads.reduce((n,r)=>n+r.triangles,0),2022);assert.ok(p.minimumRoadGap>.52);assert.equal(p.originalSpriteEnvelopeClearance.checkedCards,141);assert.ok(p.originalSpriteEnvelopeClearance.minimumGap>.37);assert.equal(p.shoreline.segments,7);assert.ok(p.shoreline.minimumGap>4.7);assert.ok(p.buildingProxyClearance.every(r=>!r.intersects));near(p.waterBacking.soleAboveWaterBacking,.075);const rect={minX:0,maxX:2,minZ:0,maxZ:2};near(segmentRectangleDistance([-1,1],[3,1],rect),0);near(segmentRectangleDistance([.5,.5],[1.5,1.5],rect),0);near(segmentRectangleDistance([-1,-1],[-1,3],rect),1);near(segmentRectangleDistance([3,3],[4,4],rect),Math.sqrt(2));assert.equal(p.originalSpriteEnvelopeClearance.allCameraProjectionOcclusionGuaranteed,false);assert.equal(f.model.scene.userData.originalArtRevision,'placement-originals1');assert.equal(f.model.scene.userData.originalArtRepresentation,'original-2d-art-in-3d-world');f.dispose();});
test('invalid anchor, crowded plaza and water positions fail without changing ordinary world or registering traversal',()=>{const f=fixture('summer'),before=JSON.stringify(f.world);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:NaN,y:10}),/anchor_invalid/);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:f.world.width*.48,y:f.world.height*.52}),/road_clearance|footprint_blocked|original_card_overlap|passage_floor_blocked/);assert.throws(()=>placeAndProbe(T,Scene,Town,f.world,f.model,f.item,{x:f.world.width-10,y:f.world.height-10}),/floor_miss|footprint_blocked/);assert.equal(JSON.stringify(f.world),before);assert.equal(f.item.group.parent,null);f.dispose();});
test('finite320and390-width camera framing covers bounds at varied yaw pitch roll without scaling the pergola',()=>{const a=build(T),scale=a.group.scale.toArray();for(const width of[300,370])for(let yaw=-180;yaw<=180;yaw+=15)for(const pitch of[-80,12,88]){const r=fitView(T,a.bounds,{yaw,pitch,roll:yaw/3,distance:1},width/350);assert.ok(Object.values(r.ndcBounds).every(v=>Number.isFinite(v)&&Math.abs(v)<.87));}assert.deepEqual(a.group.scale.toArray(),scale);a.dispose();});
test('one shared geometry/four materials dispose exactlyonce,324 actual triangles and zero added lights or textures',()=>{const a=build(T),b=build(T);assert.deepEqual(a.budget,{meshes:27,geometries:1,materials:4,textures:0,triangles:324,lights:0});let light=0;a.group.traverse(o=>{if(o.isLight)light++;});assert.equal(light,0);const resources=Object.values(a.resources).flatMap(s=>[...s]);let disposed=0;for(const r of resources)r.addEventListener('dispose',()=>disposed++);a.dispose();a.dispose();assert.equal(disposed,5);assert.equal(a.group.children.length,0);assert.equal(b.disposed,false);b.dispose();});
test('final source/dependency pins and finitecertificate agree; manual viewer uses scoped captures and no game save/registration',()=>{const m=JSON.parse(fs.readFileSync(path.join(base,'input-manifest.json'))),sha=b=>crypto.createHash('sha256').update(b).digest('hex');assert.equal(m.model_id,spec.id);assert.equal(m.base_main_sha,'db02cc6d0d7aea651511c96c736fbacf25ace510');assert.equal(m.new_mesh_candidate,1);for(const k of['normal_game_changes','new_raw_PNGs','new_original_PNG_designs','imagegen_calls'])assert.equal(m[k],0);for(const r of m.inputs){const b=fs.readFileSync(path.resolve(import.meta.dirname,'..',r.path));assert.equal(b.length,r.bytes);assert.equal(sha(b),r.sha256);}for(const r of m.files){const b=fs.readFileSync(path.join(base,r.path));assert.equal(b.length,r.bytes);assert.equal(sha(b),r.sha256);}const c=JSON.parse(fs.readFileSync(path.join(base,'finite-geometry-certificate.json')));assert.equal(c.passages.blocked,0);assert.equal(c.passages.sampleCount,252);assert.ok(c.joints.every(x=>x.insideA&&x.insideB));assert.equal(c.normalGamePlacement,false);assert.equal(c.native_views_verified_by_this_certificate,false);const v=fs.readFileSync(path.join(base,'viewer.mjs'),'utf8'),e=fs.readFileSync(path.join(base,'entry.mjs'),'utf8');assert.match(v,/window.app=/);assert.match(v,/fetch\('\/__capture\/pergola'/);assert.match(v,/toDataURL\('image\/png'\)/);assert.match(v,/visibilitychange/);assert.match(v,/pagehide/);assert.doesNotMatch(v,/localStorage|sessionStorage|saveGame|registerAsset|setInterval/);assert.match(e,/automaticRetry:false/);assert.match(e,/rawMessageStackOrURLSaved:false/);});
